metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {

    model {
        customer = person "Customer" "Looks up the status of their parcels on the Parcel Tracker."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform that lets customers look up shipments and dispatches parcels to couriers." {
            webPortal = container "Web Portal" "Where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers and sends customer notification emails. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Database" "Stores shipment and dispatch records." "SQL database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "A third-party email service operated by a different organization that delivers notification emails." "External"

        customer -> parcelTracker "looks up parcel status in" "HTTPS/JSON"
        parcelTracker -> emailProvider "sends customer notification emails to" "SMTP"

        customer -> webPortal "looks up shipment status in" "HTTPS/JSON"
        webPortal -> database "stores and retrieves shipment records in" "SQL"
        dispatchService -> database "stores and retrieves dispatch records in" "SQL"
        dispatchService -> emailProvider "sends customer notification emails to" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram of the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Container diagram of the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}
